mapper.select:
SELECT
    s.id    AS subject_id,
    s.name  AS subject_name,
    s.grade AS grade
FROM subject s
WHERE s.teacher_id = #{teacherId}
  AND s.grade = #{studentGrade}
  AND NOT EXISTS (
      SELECT 1 FROM score sc
      WHERE sc.subject_id = s.id AND sc.student_id = #{studentId}
  )
ORDER BY s.id

SELECT EXISTS (
    SELECT 1 FROM subject
    WHERE teacher_id = #{teacherId} AND grade = #{grade}
)

mapper.sql:
FROM subject s
WHERE s.teacher_id = #{teacherId}

    AND s.name LIKE CONCAT('%', #{keyword}, '%')

mapper.select:
SELECT s.id, s.name, s.teacher_id, s.grade, s.created_at

ORDER BY

    ${orderBy}
    s.id ASC

LIMIT #{offset}, #{size}

mapper.update:
UPDATE subject
   SET name  = #{name},
       grade = #{grade}
 WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM subject
WHERE teacher_id = #{teacherId}
  AND LOWER(name) = LOWER(#{name})

SELECT COUNT(*) FROM subject
WHERE teacher_id = #{teacherId}
  AND LOWER(name) = LOWER(#{name})
  AND id != #{excludingId}
